      unit: bi('יח״ד', 'housing units'), geography: bi('מתחם · יישוב · מחוז · ארצי', 'Complex · locality · district · national'), period: bi('כפי שפורסם; תאריך ההכרזה לכל מתחם', 'As published; the declaration date per complex'),
