      unit: bi('חודשים', 'months'), geography: bi('ארצי · מחוז (סדרת המחוז); יישוב → "—"', 'National · district (the district series); locality → "—"'), period: bi('זכיות 24 חודשים; מכירות 12 חודשים', 'Awards 24 months; sales 12 months'),
      source: { ids: ['rmi:michrazim', 'cbs:new-home-sales', 'propx:supply'] }, cls: 'DERIVED',
      formula: bi('יח״ד שנזכו (24 ח׳) ÷ (Σ מכירות 12 ח׳ ÷ 12)', 'units awarded (24 m) ÷ (Σ sales 12 m ÷ 12)'), inputs: [bi('יח״ד במגרשים שנזכו (רשמי, קרקע מדינה)', 'units in awarded lots (OFFICIAL, state land)'), bi('מכירות דירות חדשות 12 חודשים (רשמי)', 'official new-home sales, 12 months')],
