      notAs: bi('לא זמן בנייה, לא "שנות היצע" (קרקע פרטית אינה נספרת), לא תחזית מחיר.', 'Not a construction time, not "years of supply" (private land is not counted), not a price forecast.'),
      limitations: [LIM.stateLand, LIM.tenderUnits, LIM.noLocalitySeries], evidence: bi('view=supply → indicators[supply-pressure] (נוסחה, קלט, חלונות)', 'view=supply → indicators[supply-pressure] (formula, inputs, windows)'),
